import java.io.DataInputStream

class FastReader(stream: java.io.InputStream) {
    private val BUFFER_SIZE = 1 shl 16
    private val din = DataInputStream(stream)
    private val buffer = ByteArray(BUFFER_SIZE)
    private var bufferPointer = 0
    private var bytesRead = 0

    fun readLong(): Long {
        var ret = 0L
        var b = read()
        while (b <= ' '.code.toByte()) b = read()
        val neg = b == '-'.code.toByte()
        if (neg) b = read()
        while (b >= '0'.code.toByte() && b <= '9'.code.toByte()) {
            ret = ret * 10 + (b - '0'.code.toByte())
            b = read()
        }
        return if (neg) -ret else ret
    }

    private fun fillBuffer() {
        bytesRead = din.read(buffer, 0, BUFFER_SIZE)
        bufferPointer = 0
        if (bytesRead == -1) {
            bytesRead = 0
            buffer[0] = -1
        }
    }

    private fun read(): Byte {
        if (bufferPointer == bytesRead) fillBuffer()
        return buffer[bufferPointer++]
    }
}

var l = 0L
var r = 0L
var ans = 0L
var q = 0
var Q = 0
var p = 0
val w = BooleanArray(99)
val W = BooleanArray(99)

fun main() {
    val fr = FastReader(System.`in`)
    l = fr.readLong()
    r = fr.readLong()
    while (l != 0L) {
        w[q++] = (l % 2) != 0L
        l = l shr 1
    }
    while (r != 0L) {
        W[Q++] = (r % 2) != 0L
        r = r shr 1
    }
    for (i in Q downTo 0) {
        if (w[i] != W[i]) {
            p = i + 1
            break
        }
    }
    ans = (1L shl p) - 1L
    print(ans)
}
